name: Auto Assign Milestone
on:
  pull_request:
    types: [opened, synchronize, reopened, edited]
  pull_request_target:
    types: [closed]

jobs:
  assign-milestone:
    runs-on: ubuntu-latest
    steps:
      - name: Check if PR is merged
        id: check_merged
        if: github.event_name == 'pull_request_target' && github.event.action == 'closed' && github.event.pull_request.merged == true
        run: |
          echo "PR merged: true"
          echo "PR number: ${{ github.event.pull_request.number }}"
          echo "Base branch: ${{ github.event.pull_request.base.ref }}"

      - name: Assign milestone based on target branch
        if: github.event_name == 'pull_request_target' && github.event.action == 'closed' && github.event.pull_request.merged == true
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = context.payload.pull_request.number;
            const baseBranch = context.payload.pull_request.base.ref;
            let milestone = null;

            // Map branches to milestones
            if (baseBranch === 'main') {
              milestone = '9.5';
            } else if (baseBranch === 'release/9.4') {
              milestone = '9.4.1';
            }

            if (milestone) {
              try {
                await github.rest.issues.update({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: prNumber,
                  milestone: milestone
                });
                console.log(`Assigned milestone ${milestone} to PR #${prNumber}`);
              } catch (error) {
                console.error(`Failed to assign milestone to PR #${prNumber}:`, error);
                throw error;
              }
            } else {
              console.log(`No milestone assigned for branch: ${baseBranch}`);
            }

      - name: Re-evaluate milestone on PR activity
        if: github.event_name == 'pull_request' || (github.event_name == 'pull_request_target' && github.event.action != 'closed')
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = context.payload.pull_request.number;
            const baseBranch = context.payload.pull_request.base.ref;
            let milestone = null;

            // Map branches to milestones
            if (baseBranch === 'main') {
              milestone = '9.5';
            } else if (baseBranch === 'release/9.4') {
              milestone = '9.4.1';
            }

            if (milestone) {
              try {
                // Get current milestone
                const { data: issue } = await github.rest.issues.get({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: prNumber
                });

                // If milestone is different or missing, update it
                if (!issue.milestone || issue.milestone.title !== milestone) {
                  await github.rest.issues.update({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    issue_number: prNumber,
                    milestone: milestone
                  });
                  console.log(`Updated milestone to ${milestone} for PR #${prNumber}`);
                }
              } catch (error) {
                console.error(`Failed to re-evaluate milestone for PR #${prNumber}:`, error);
                throw error;
              }
            } else {
              console.log(`No milestone assigned for branch: ${baseBranch}`);
            }
